<script lang="ts">import { SvelteSet } from 'svelte/reactivity';
import { useStudio } from '../../internal/extensions';
import { studioObjectsRegistryScope } from './types';
const { createExtension } = useStudio();
createExtension({
    scope: studioObjectsRegistryScope,
    state() {
        return {
            objects: new SvelteSet()
        };
    },
    actions: {
        addObject({ state }, object) {
            state.objects.add(object);
        },
        removeObject({ state }, object) {
            state.objects.delete(object);
        }
    }
});
</script>

<slot />
